// =============================================================================
// SIMULADOR DO CLP (desenvolvimento sem a bancada). Ativo só com INPUT_MODE=SIMULADOR.
// Gera um snapshot com OS MESMOS NOMES de variáveis do nó "s7 in" (modo "all").
// Botões: msg.topic = "sim_cmd", msg.payload = START | STOP | EMERGENCY | RESET
// =============================================================================
if ((env.get("INPUT_MODE") || "SIMULADOR") !== "SIMULADOR") { return null; }

let sim = context.get("sim") || { running: false, emergency: false, pulse: null, pulseTicks: 0, op: 1 };

if (msg.topic === "sim_cmd") {
    const cmd = String(msg.payload || "").toUpperCase();
    if (cmd === "START" && !sim.emergency) { sim.running = true; sim.pulse = "START"; }
    if (cmd === "STOP")      { sim.running = false; sim.pulse = "STOP"; }
    if (cmd === "EMERGENCY") { sim.running = false; sim.emergency = true; sim.pulse = null; }
    if (cmd === "RESET")     { sim.emergency = false; sim.pulse = null; }
    sim.pulseTicks = 3;                         // botão "fica apertado" ~300 ms
    context.set("sim", sim);
    node.status({ fill: "blue", shape: "ring", text: "SIM: " + cmd });
    return null;
}

const green = sim.pulseTicks > 0 && sim.pulse === "START";
const red   = sim.pulseTicks > 0 && sim.pulse === "STOP";
if (sim.pulseTicks > 0) { sim.pulseTicks--; }
context.set("sim", sim);

const belts = sim.running && !sim.emergency;
const station = (p) => ({
    [p + "_segurancaOK"]: !sim.emergency,
    [p + "_chaveAutomatico"]: true,
    [p + "_botaoVerde"]: green,
    [p + "_botaoVermelho"]: red,
    [p + "_esteira1"]: belts,
    [p + "_esteira2"]: belts
});

msg.payload = Object.assign(
    {
        emergencia: sim.emergency, emergenciaAtivada: sim.emergency,
        ocupado: belts, aguardando: !belts, manual: false,
        comutadorAutomatico: true, condicaoIniciar: !sim.emergency,
        numeroOP: sim.op, montagem_pecaStopper: belts, expedicao_pecaStopper: false
    },
    station("processo"), station("montagem"), station("expedicao")
);
msg.source = "SIMULATOR";
node.status({ fill: sim.emergency ? "red" : (belts ? "green" : "grey"), shape: "dot",
              text: sim.emergency ? "SIM: EMERGÊNCIA" : (belts ? "SIM: RODANDO" : "SIM: PARADO") });
return msg;

// =============================================================================
// REPLAY: recebe um snapshot capturado na bancada (POST /replay/s7) e injeta no
// pipeline como se viesse do nó "s7 in". Usado por tools/replay-telemetria.js.
// Corpo: { "captured_at": "ISO", "vars": { emergencia: false, ... } }
// Saída 1 -> pipeline · Saída 2 -> resposta HTTP
// =============================================================================
const mode = env.get("INPUT_MODE") || "SIMULADOR";
const body = msg.payload || {};
const res = { req: msg.req, res: msg.res, headers: { "Content-Type": "application/json" } };

if (mode !== "REPLAY") {
    return [null, Object.assign(res, { statusCode: 409,
        payload: { erro: "INPUT_MODE=" + mode + ". Mude a variável INPUT_MODE da aba para REPLAY e faça Deploy." } })];
}
if (!body.vars || typeof body.vars !== "object") {
    return [null, Object.assign(res, { statusCode: 400, payload: { erro: "Campo 'vars' ausente no corpo" } })];
}
const n = (context.get("count") || 0) + 1;
context.set("count", n);
node.status({ fill: "blue", shape: "dot", text: "replay: " + n + " leituras" });
return [
    { payload: body.vars, source: "REPLAY", captured_at: body.captured_at || null },
    Object.assign(res, { statusCode: 202, payload: { aceito: true, n: n } })
];

// =============================================================================
// FONTE ATIVA: deixa passar só a fonte escolhida em INPUT_MODE
//   CLP       -> leituras do nó "s7 in" (bancada real)
//   SIMULADOR -> simulador interno
//   REPLAY    -> capturas reinjetadas por tools/replay-telemetria.js
// Saída 1 -> normalização · Saída 2 -> captura em arquivo (se CAPTURE=true)
// =============================================================================
const MAP = { CLP: "PLC", SIMULADOR: "SIMULATOR", REPLAY: "REPLAY" };
const mode = env.get("INPUT_MODE") || "SIMULADOR";
const source = msg.source || "PLC";               // o nó "s7 in" não marca a origem
if (MAP[mode] !== source) { return null; }
msg.source = source;

let capture = null;
if (env.get("CAPTURE") === "true" && source === "PLC") {
    // Uma linha JSON por leitura (formato lido pelo replay)
    capture = {
        filename: global.get("captureFile") || "captura-n2.jsonl",
        payload: JSON.stringify({ t: new Date().toISOString(), source: source, vars: msg.payload })
    };
}
return [msg, capture];

// =============================================================================
// NORMALIZAÇÃO: snapshot bruto do CLP -> amostra padronizada (uma a cada 100 ms)
// Mesma regra de machine_state da Sprint 1 (HIPÓTESE a validar na bancada,
// ver docs/mapeamento-clp.md e docs/tags/inventario_mapa_tags_n2.xlsx).
// =============================================================================
const r = msg.payload || {};
const b = (k) => r[k] === true;
const NOMINAL = parseFloat(env.get("BELT_NOMINAL_SPEED"));

const st = (p) => ({
    seguranca_ok: b(p + "_segurancaOK"),
    automatico: b(p + "_chaveAutomatico"),
    botao_verde: b(p + "_botaoVerde"),
    botao_vermelho: b(p + "_botaoVermelho"),
    esteira1: b(p + "_esteira1"),
    esteira2: b(p + "_esteira2")
});
const stations = { processo: st("processo"), montagem: st("montagem"), expedicao: st("expedicao") };
const list = Object.values(stations);

const emergency   = b("emergencia") || b("emergenciaAtivada");
const beltRunning = list.some(s => s.esteira1 || s.esteira2);
const safetyFault = list.some(s => !s.seguranca_ok);

let state;
if (emergency)                        state = "EMERGENCY";
else if (safetyFault)                 state = "ALARM";
else if (beltRunning || b("ocupado")) state = "RUNNING";
else if (b("manual"))                 state = "PAUSED";
else                                  state = "STOPPED";

// Velocidade: só existe se o CLP tiver o registrador (ex. do enunciado: DB1.DBD4, a confirmar).
let beltSpeed = 0, speedSource = "PLC_DIGITAL";
if (typeof r.velocidadeEsteira === "number") { beltSpeed = r.velocidadeEsteira; speedSource = "PLC_ANALOG"; }
else if (beltRunning) {
    if (isNaN(NOMINAL)) { beltSpeed = null; speedSource = "UNAVAILABLE"; }
    else                { beltSpeed = NOMINAL; speedSource = "NOMINAL_CONFIG"; }
}

msg.payload = {
    t: Date.now(),
    source: msg.source,
    captured_at: msg.captured_at || null,
    machine_state: state,
    belt_running: beltRunning,
    belt_speed: beltSpeed,
    belt_speed_source: speedSource,
    buttons: {
        start_pressed: list.some(s => s.botao_verde),
        stop_pressed: list.some(s => s.botao_vermelho),
        emergency_pressed: emergency,
        reset_pressed: false              // sem endereço de Reset no mapa (pendência)
    },
    stations: stations,
    flags: {
        ocupado: b("ocupado"), aguardando: b("aguardando"), manual: b("manual"),
        comutador_automatico: b("comutadorAutomatico"), condicao_iniciar: b("condicaoIniciar")
    },
    presence: { montagem: b("montagem_pecaStopper"), expedicao: b("expedicao_pecaStopper") },
    numero_op: typeof r.numeroOP === "number" ? r.numeroOP : null
};
return msg;

// =============================================================================
// AGREGADOR 500 ms: junta as amostras de 100 ms e emite UMA mensagem por janela.
// - Estado/valores: os da ÚLTIMA amostra da janela.
// - Botões: OU lógico na janela -> um toque de 100 ms nunca se perde.
// - aggregation: quantas amostras, % de tempo com esteira ligada, estados vistos.
// Entradas: amostra normalizada | msg.topic "__flush__" (inject a cada 500 ms)
// =============================================================================
const WINDOW_MS = Number(env.get("AGG_WINDOW_MS") || 500);
const MACHINE_ID = env.get("MACHINE_ID") || "SMART-40-PLANTA-N2";
let w = context.get("w");

if (msg.topic !== "__flush__") {
    const s = msg.payload;
    if (!w) {
        w = { start: s.t, n: 0, belt: 0, states: [], changes: 0, prevState: null,
              buttons: { start_pressed: false, stop_pressed: false, emergency_pressed: false, reset_pressed: false } };
    }
    w.n += 1;
    if (s.belt_running) w.belt += 1;
    if (w.states.indexOf(s.machine_state) < 0) w.states.push(s.machine_state);
    if (w.prevState !== null && w.prevState !== s.machine_state) w.changes += 1;
    w.prevState = s.machine_state;
    for (const k in w.buttons) { w.buttons[k] = w.buttons[k] || s.buttons[k] === true; }
    w.last = s;
    context.set("w", w);
    return null;
}

// ---- fim da janela ----
if (!w || w.n === 0) {
    node.status({ fill: "grey", shape: "ring", text: "sem leituras da fonte" });
    return null;
}
context.set("w", null);
const s = w.last;
const prevFinal = context.get("prevFinal");
// Emergência é estado travado (já aparece em machine_state); START/STOP são toques.
const changed = w.changes > 0 || (prevFinal !== undefined && prevFinal !== s.machine_state)
             || w.buttons.start_pressed || w.buttons.stop_pressed;
context.set("prevFinal", s.machine_state);

const seq = (context.get("seq") || 0) + 1;
context.set("seq", seq);
const now = Date.now();

msg.topic = env.get("MQTT_TOPIC_DATA") || "industria40/telemetry/data";
msg.payload = {
    schema_version: "1.1",                       // 1.1 = 1.0 + bloco "aggregation" (compatível)
    msg_id: MACHINE_ID + "-" + s.t + "-" + seq + "-" + Math.random().toString(36).slice(2, 8),
    machine_id: MACHINE_ID,
    timestamp: new Date(s.t).toISOString(),      // momento da última leitura da janela
    seq: seq,
    event: changed ? "STATE_CHANGE" : "PERIODIC",
    source: s.source,
    buffered: false,
    machine_state: s.machine_state,
    belt_running: s.belt_running,
    belt_speed: s.belt_speed,
    belt_speed_source: s.belt_speed_source,
    buttons: w.buttons,
    stations: s.stations,
    flags: s.flags,
    presence: s.presence,
    numero_op: s.numero_op,
    aggregation: {
        window_ms: WINDOW_MS,
        samples: w.n,
        window_start: new Date(w.start).toISOString(),
        window_end: new Date(s.t).toISOString(),
        belt_running_ratio: Math.round((w.belt / w.n) * 100) / 100,
        states_seen: w.states,
        state_changes: w.changes
    }
};
if (s.captured_at) msg.payload.replay = { captured_at: s.captured_at };

flow.set("last_telemetry", msg.payload);
// Últimas mensagens (GET /edge/recent) — usado pela validação de replay
const recent = flow.get("recent") || [];
recent.push(msg.payload);
if (recent.length > 3000) recent.splice(0, recent.length - 3000);
flow.set("recent", recent);
node.status({ fill: "green", shape: "dot", text: s.machine_state + " · " + w.n + " amostras · seq " + seq });
return msg;

// =============================================================================
// OUTBOX (SQLite) — grava TODA mensagem antes de qualquer envio (Outbox Pattern).
// O envio acontece no "Outbox: despacha"; a linha só vira SENT com o PUBACK do broker.
// =============================================================================
const db = global.get("outbox_db");
if (!db) { node.status({ fill: "red", shape: "ring", text: "outbox fechada" }); node.error("Outbox indisponível", msg); return null; }
const MAX = Number(env.get("OUTBOX_MAX") || 200000);
const p = msg.payload;
const online = flow.get("mqtt_online") === true && flow.get("force_offline") !== true;

db.prepare(`INSERT OR IGNORE INTO outbox_telemetry (msg_id, topic, payload, created_offline, created_at)
            VALUES (?, ?, ?, ?, ?)`)
  .run(p.msg_id, msg.topic, JSON.stringify(p), online ? 0 : 1, new Date().toISOString());

const pending = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
if (pending > MAX) {
    const excess = pending - MAX;
    db.prepare(`DELETE FROM outbox_telemetry WHERE id IN
                (SELECT id FROM outbox_telemetry WHERE status = 'PENDING' ORDER BY id LIMIT ?)`).run(excess);
    node.warn("Outbox cheia (" + MAX + "). Descartadas " + excess + " mensagens mais antigas.");
}
node.status({ fill: online ? "green" : "yellow", shape: "dot", text: "pendentes: " + Math.min(pending, MAX) });
return null;

