// Abre o SQLite da outbox e cria a tabela (mesmo DDL de db/002_outbox_telemetry.sql).
// Requer Node.js >= 22.13 (módulo nativo node:sqlite) e o bloco functionGlobalContext
// do node-red/settings.js.
const sqlite = global.get("sqlite");
if (!sqlite) {
    node.status({ fill: "red", shape: "ring", text: "SQLite indisponível (Node.js >= 22.13?)" });
    node.error("node:sqlite indisponível. Use Node.js 22.13+ e o settings.js do repositório.");
    return;
}
const file = global.get("outboxPath") || "outbox_n2.sqlite";
const db = new sqlite.DatabaseSync(file);
db.exec("PRAGMA journal_mode = WAL;");
db.exec(`CREATE TABLE IF NOT EXISTS outbox_telemetry (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    msg_id           TEXT    NOT NULL UNIQUE,
    topic            TEXT    NOT NULL,
    payload          TEXT    NOT NULL,
    status           TEXT    NOT NULL DEFAULT 'PENDING'
                     CHECK (status IN ('PENDING', 'INFLIGHT', 'SENT')),
    created_offline  INTEGER NOT NULL DEFAULT 0,
    attempts         INTEGER NOT NULL DEFAULT 0,
    created_at       TEXT    NOT NULL,
    last_attempt_at  TEXT,
    sent_at          TEXT,
    last_error       TEXT
);
CREATE INDEX IF NOT EXISTS idx_outbox_status_id ON outbox_telemetry (status, id);
CREATE INDEX IF NOT EXISTS idx_outbox_sent_at ON outbox_telemetry (sent_at);
`);
global.set("outbox_db", db);
const n = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
node.status({ fill: "green", shape: "dot", text: "outbox aberta · pendentes " + n });

finalize:
const db = global.get("outbox_db");
if (db) { try { db.close(); } catch (e) { /* já fechado */ } }
global.set("outbox_db", undefined);

func:
// =============================================================================
// OUTBOX — despachante (envio garantido, "pelo menos uma vez", em ordem)
//  1. Só envia com o MQTT conectado.
//  2. INFLIGHT sem PUBACK há mais de ACK_TIMEOUT_MS volta para PENDING (reenvio).
//  3. Enquanto houver INFLIGHT, não manda lote novo -> ordem preservada.
//  4. Lote de até OUTBOX_BATCH linhas: PENDING -> INFLIGHT e sai para o "mqtt out".
// Mensagem que esperou na outbox sai com buffered=true. Duplicata de reenvio é
// descartada pelo iot-service (msg_id).
// Entradas: tick (__tick__), status do mqtt out, __force_offline__/__force_online__
// =============================================================================
const db = global.get("outbox_db");
if (!db) { return null; }
const ACK_MS = Number(env.get("ACK_TIMEOUT_MS") || 5000);
const BATCH  = Number(env.get("OUTBOX_BATCH") || 100);

function isOnline() { return flow.get("mqtt_online") === true && flow.get("force_offline") !== true; }
function count(st) { return db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status = ?").get(st).n; }
function show() {
    const p = count("PENDING"), f = count("INFLIGHT");
    node.status(isOnline()
        ? { fill: p + f ? "yellow" : "green", shape: "dot", text: "online · pendentes " + p + " · aguardando PUBACK " + f }
        : { fill: "red", shape: "ring", text: "OFFLINE · " + (p + f) + " msg na outbox" });
}

if (msg.status) {
    const was = isOnline();
    flow.set("mqtt_online", msg.status.fill === "green");
    if (!was && isOnline()) node.warn("MQTT reconectado. Na outbox: " + (count("PENDING") + count("INFLIGHT")));
} else if (msg.topic === "__force_offline__") {
    flow.set("force_offline", true);
} else if (msg.topic === "__force_online__") {
    flow.set("force_offline", false);
}
if (!isOnline()) { show(); return null; }

const now = Date.now();
db.prepare(`UPDATE outbox_telemetry SET status = 'PENDING', last_error = 'sem PUBACK'
            WHERE status = 'INFLIGHT' AND last_attempt_at < ?`).run(new Date(now - ACK_MS).toISOString());
if (count("INFLIGHT") > 0) { show(); return null; }

const rows = db.prepare(`SELECT id, topic, payload, created_offline, attempts FROM outbox_telemetry
                         WHERE status = 'PENDING' ORDER BY id LIMIT ?`).all(BATCH);
if (rows.length === 0) { show(); return null; }

const iso = new Date(now).toISOString();
const mark = db.prepare(`UPDATE outbox_telemetry SET status = 'INFLIGHT', attempts = attempts + 1,
                         last_attempt_at = ? WHERE id = ?`);
db.exec("BEGIN");
try { rows.forEach(r => mark.run(iso, r.id)); db.exec("COMMIT"); }
catch (e) { db.exec("ROLLBACK"); throw e; }

const out = rows.map(r => {
    const p = JSON.parse(r.payload);
    if (r.created_offline === 1 || r.attempts > 0) p.buffered = true;
    return { topic: r.topic, payload: p, qos: 1, retain: false, outbox_id: r.id };
});
show();
return [out];

// PUBACK recebido (nó "complete" observando o "mqtt out"): a linha vira SENT.
const db = global.get("outbox_db");
if (!db || msg.outbox_id === undefined) { return null; }
db.prepare("UPDATE outbox_telemetry SET status = 'SENT', sent_at = ?, last_error = NULL WHERE id = ?")
  .run(new Date().toISOString(), msg.outbox_id);
const n = (context.get("n") || 0) + 1;
context.set("n", n);
node.status({ fill: "green", shape: "dot", text: "confirmadas (PUBACK): " + n });
return null;

// Erro no publish (nó "catch" do "mqtt out"): volta para PENDING para reenviar.
const db = global.get("outbox_db");
if (!db || msg.outbox_id === undefined) { return null; }
const err = (msg.error && msg.error.message) || "erro no publish";
db.prepare("UPDATE outbox_telemetry SET status = 'PENDING', last_error = ? WHERE id = ? AND status = 'INFLIGHT'")
  .run(String(err).slice(0, 200), msg.outbox_id);
node.status({ fill: "red", shape: "ring", text: err });
return null;

// Apaga o que já foi confirmado há mais de OUTBOX_RETENTION_H horas (padrão 24 h).
const db = global.get("outbox_db");
if (!db) { return null; }
const hours = Number(env.get("OUTBOX_RETENTION_H") || 24);
const limit = new Date(Date.now() - hours * 3600 * 1000).toISOString();
const r = db.prepare("DELETE FROM outbox_telemetry WHERE status = 'SENT' AND sent_at < ?").run(limit);
node.status({ text: "removidas: " + r.changes + " (" + new Date().toLocaleTimeString() + ")" });
return null;

// GET /edge/status -> diagnóstico LOCAL do gateway (usado também pelo replay)
const db = global.get("outbox_db");
const counts = { PENDING: 0, INFLIGHT: 0, SENT: 0 };
if (db) {
    db.prepare("SELECT status, COUNT(*) AS n FROM outbox_telemetry GROUP BY status").all()
      .forEach(r => { counts[r.status] = r.n; });
}
msg.payload = {
    input_mode: env.get("INPUT_MODE") || "SIMULADOR",
    capture: env.get("CAPTURE") === "true",
    mqtt_online: flow.get("mqtt_online") === true,
    forced_offline: flow.get("force_offline") === true,
    outbox_ready: !!db,
    outbox: counts,
    last_telemetry: flow.get("last_telemetry") || null
};
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;

// GET /edge/recent?since_seq=N -> mensagens agregadas recentes (até 3000), em ordem
const since = Number((msg.req && msg.req.query && msg.req.query.since_seq) || 0);
msg.payload = (flow.get("recent") || []).filter(m => m.seq > since);
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;
